## The derivation script (not committed)

`scripts/check-published-readme-exports.mjs` is fenced on this card — this is a read, not a recognizer change — so the site-list derivation lives here rather than in the tree. Reproduced in full so the measurement in PR #10816 is checkable.

It reuses the gate's own exports and re-states only two things: `analyzeDocument`'s `readable` map (built internally, not exported) and `countUnreadCalls`' body (which returns cardinalities, not the pairs). The re-statement is **checksummed against the gate** rather than trusted — summed over all 60 published documents it must reproduce the printed `NOT read:` pair, and it does in both directions (`120 / 72` before the repairs, `119 / 71` after). It also self-checks each document against the real `countUnreadCalls` and prints a `MISMATCH` line if they disagree; none were printed.

Run from a built worktree: `node derive-unread.mjs packages/runtime/README.md`. The absolute paths at the top are this worktree's; change them to run it elsewhere.

```js
// Derive the gate's OWN `NOT read` population, per document, and print the sites.
// Reuses the gate's exported extractors verbatim; the only thing re-stated here is
// `analyzeDocument`'s `readable` map (which the gate does not export) and
// `countUnreadCalls`'s body (which returns counts, not the site list).
//
// Validity check built in: the per-document totals must sum to the gate's printed
// `NOT read: <calls> ... on <receivers>` pair. If they do not, this derivation is
// not the gate's population and its output must be discarded.
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import {
  publishedDocs,
  extractImports,
  splitSpecifier,
  resolveTypesEntry,
  extractLocalBindings,
  readFences,
  countUnreadCalls,
} from '/home/user/objectstack-10368/scripts/check-published-readme-exports.mjs';

const ROOT = '/home/user/objectstack-10368';
const { byName, docs } = publishedDocs();

function readableNamesFor(doc) {
  const bound = new Set();
  for (const imp of extractImports(doc.text)) {
    const split = splitSpecifier(imp.specifier);
    if (!split) continue;
    if (!byName.has(split.name)) continue;
    const { dir, manifest } = byName.get(split.name);
    const { entry, declared } = resolveTypesEntry(manifest, split.subpath);
    if (!declared) continue;
    const abs = entry ? join(ROOT, dir, entry.replace(/^\.\//, '')) : null;
    if (!abs || !existsSync(abs)) continue;
    for (const { local } of imp.named) bound.add(local);
    if (imp.defaultLocal) bound.add(imp.defaultLocal);
    // namespaceLocal: gate binds it only when the target supplies a module symbol.
    if (imp.namespaceLocal) bound.add(imp.namespaceLocal);
  }
  const readable = new Set(bound);
  const { bound: derived } = extractLocalBindings(doc.text, [...bound]);
  for (const [local, { source }] of derived) {
    if (readable.has(local)) continue;
    if (!bound.has(source)) continue;
    readable.add(local);
  }
  return readable;
}

function unreadSites(markdown, readable) {
  const sites = new Map(); // "X.y" -> [lines]
  for (const fence of readFences(markdown)) {
    for (const { n, text } of fence.lines) {
      if (/^\s*(import\b|\/\/|\*|\/\*)/.test(text)) continue;
      const rx = /(?<[\w$.'"`])([A-Za-z_$][\w$]*)\s*\.\s*([A-Za-z_$][\w$]*)\s*\(/g;
      let m;
      while ((m = rx.exec(text)) !== null) {
        if (readable.has(m[1])) continue;
        const key = `${m[1]}.${m[2]}`;
        if (!sites.has(key)) sites.set(key, []);
        sites.get(key).push(n);
      }
    }
  }
  return sites;
}

let totalCalls = 0;
let totalReceivers = 0;
const perDoc = [];
for (const doc of docs) {
  const readable = readableNamesFor(doc);
  const cross = countUnreadCalls(doc.text, [...readable]);
  const sites = unreadSites(doc.text, readable);
  const receivers = new Set([...sites.keys()].map((k) => k.split('.')[0]));
  if (sites.size !== cross.calls || receivers.size !== cross.receivers) {
    console.error(`MISMATCH in ${doc.file}: mine ${sites.size}/${receivers.size} vs countUnreadCalls ${cross.calls}/${cross.receivers}`);
  }
  totalCalls += cross.calls;
  totalReceivers += cross.receivers;
  if (sites.size) perDoc.push({ file: doc.file, calls: sites.size, receivers: receivers.size, sites });
}

console.log(`TOTAL unread calls=${totalCalls} receivers=${totalReceivers}  (gate must print the same pair)`);
perDoc.sort((a, b) => b.calls - a.calls);
console.log('\n--- per document (descending) ---');
for (const d of perDoc) console.log(`${String(d.calls).padStart(3)} call(s) / ${String(d.receivers).padStart(2)} receiver(s)  ${d.file}`);

const target = process.argv[2];
if (target) {
  const d = perDoc.find((x) => x.file === target);
  if (!d) { console.log(`\n${target}: no unread sites`); process.exit(0); }
  console.log(`\n--- ${target}: ${d.calls} site(s) on ${d.receivers} receiver(s) ---`);
  const byRecv = new Map();
  for (const [k, lines] of d.sites) {
    const [r, m] = k.split('.');
    if (!byRecv.has(r)) byRecv.set(r, []);
    byRecv.get(r).push({ member: m, lines });
  }
  let i = 0;
  for (const [r, list] of [...byRecv.entries()].sort((a, b) => b[1].length - a[1].length)) {
    console.log(`\nreceiver \`${r}\`  (${list.length} site(s))`);
    for (const { member, lines } of list) console.log(`  ${String(++i).padStart(2)}. ${r}.${member}(…)   line(s): ${lines.join(', ')}`);
  }
}
```

